def compute_utility(rewards, discount):
    return sum(r * discount ** i for i, r in enumerate(rewards))
walk = [-1] * 9                      # 1→10 을 걷기만: 보상 −1 이 9 번
for g in [1, 0.99, 0.9, 0.5, 0]:
    print(g, round(compute_utility(walk, g), 4))
# 할인이 결정을 바꾸는 예: 지금 2 vs 세 걸음 뒤 3
for g in [1, 0.9, 0.5]:
    now, later = compute_utility([2], g), compute_utility([0, 0, 0, 3], g)
    print(g, "now" if now > later else "later", round(now, 3), round(later, 3))

import random, statistics
def tram_step(s, a, n=10, p=0.4):
    if a == "walk": return -1, s + 1
    return -2, (2 * s if random.random() < 1 - p else s)
def rollout_utility(policy, n=10):
    s, u = 1, 0
    while s != n:
        r, s = tram_step(s, policy(s)); u += r
    return u
tram_if_possible = lambda s: "tram" if 2 * s <= 10 else "walk"
random.seed(0)
for k in [20, 100, 10_000]:
    us = [rollout_utility(tram_if_possible) for _ in range(k)]
    m, sd = statistics.mean(us), statistics.pstdev(us)
    print(k, round(m, 3), "± about", round(sd / k ** 0.5, 3))

def compute_distance(v1, v2):            # L∞: 상태별 차이 중 가장 큰 것
    return max(abs(v1[s] - v2[s]) for s in v1)
values     = {1: 0.2, 2: 1.0, 3: -1.0}
new_values = {1: 0.2, 2: 1.1, 3: 1.0}
print(compute_distance(values, new_values))        # 2.0 — 상태 3 이 아직 멀다
avg = sum(abs(values[s] - new_values[s]) for s in values) / 3
print(round(avg, 3), "← 평균을 쓰면 상태 3 의 큰 차이가 묻힌다")

def succ(s, n=10, p=0.4):                # {action: [(prob, reward, s')]}
    d = {"walk": [(1.0, -1, s + 1)]} if s + 1 <= n else {}
    if 2 * s <= n: d["tram"] = [(1 - p, -2, 2 * s), (p, -2, s)]
    return d
def q(trans, V, g): return sum(p * (r + g * V[s2]) for p, r, s2 in trans)
def policy_evaluation(policy, n=10, g=1.0, tol=1e-5):
    V = {s: (0 if s == n else -100) for s in range(1, n + 1)}
    for it in range(1, 1000):
        new = {s: 0 if s == n else q(succ(s)[policy(s)], V, g) for s in V}
        dist = max(abs(new[s] - V[s]) for s in V)
        if it <= 2: print(it, {s: round(v, 2) for s, v in new.items()})
        V = new
        if dist < tol: return V, it
tram_if_possible = lambda s: "tram" if 2 * s <= 10 else "walk"
V, it = policy_evaluation(tram_if_possible)
print("iters", it, {s: round(v, 4) for s, v in V.items()})
print("walk only:", policy_evaluation(lambda s: "walk")[0][1])

def succ(s, n=10, p=0.4):
    d = {"walk": [(1.0, -1, s + 1)]} if s + 1 <= n else {}
    if 2 * s <= n: d["tram"] = [(1 - p, -2, 2 * s), (p, -2, s)]
    return d
def q(trans, V, g=1.0): return sum(pr * (r + g * V[s2]) for pr, r, s2 in trans)
def value_iteration(n=10, tol=1e-5):
    V = {s: (0 if s == n else -100) for s in range(1, n + 1)}; pi = {}
    for it in range(1, 1000):
        new = dict(V)
        for s in range(1, n):
            qs = {a: q(t, V) for a, t in succ(s).items()}
            pi[s] = max(qs, key=qs.get); new[s] = qs[pi[s]]   # 차이는 이 max 하나
        dist = max(abs(new[s] - V[s]) for s in V)
        if it in (1, 2, 3, 5): print(it, [round(new[s], 2) for s in range(1, n)], round(dist, 2))
        V = new
        if dist < tol: return V, pi, it
V, pi, it = value_iteration()
print("iters", it, [round(V[s], 3) for s in range(1, 10)])
print(pi)
print({a: round(q(t, V), 3) for a, t in succ(4).items()}, {a: round(q(t, V), 3) for a, t in succ(1).items()})

import numpy as np
n, p = 10, 0.4
def succ(s):
    d = {"walk": [(1.0, -1, s + 1)]} if s + 1 <= n else {}
    if 2 * s <= n: d["tram"] = [(1 - p, -2, 2 * s), (p, -2, s)]
    return d
def evaluate(pi):                        # (I − P_π)V = r_π 를 정확히 푼다
    A, b = np.eye(n), np.zeros(n)        # 인덱스 s−1, 끝 상태 10 은 V = 0
    for s in range(1, n):
        for pr, r, s2 in succ(s)[pi[s]]:
            b[s-1] += pr * r; A[s-1, s2-1] -= pr
    return np.linalg.solve(A, b)
def q(V, trans): return sum(pr * (r + V[s2-1]) for pr, r, s2 in trans)
pi = {s: "walk" for s in range(1, n)}    # 시작: 항상 걷기
for k in range(1, 10):
    V = evaluate(pi)
    new = {s: max(succ(s), key=lambda a: q(V, succ(s)[a])) for s in range(1, n)}
    print(k, np.round(V[:9], 3), [s for s in new if new[s] == "tram"])
    if new == pi: break
    pi = new
